import { 
  createUserWithEmailAndPassword, 
  sendEmailVerification,
  signInWithEmailAndPassword,
  signOut,
  updateProfile,
  UserCredential
} from 'firebase/auth';
import { auth } from '@/lib/firebase-config';
import { toast } from 'sonner';

/**
 * Register a new user with email and password
 */
export const registerUser = async (
  email: string,
  password: string,
  displayName: string
): Promise<UserCredential | null> => {
  try {
    console.log('Attempting Firebase registration for:', email);
    
    // Create user account
    const userCredential = await createUserWithEmailAndPassword(auth, email, password);
    
    console.log('Firebase user created:', userCredential.user.uid);
    
    // Update user profile with display name
    if (userCredential.user) {
      await updateProfile(userCredential.user, { displayName });
      
      console.log('Profile updated with displayName:', displayName);
      
      // Send email verification
      await sendEmailVerification(userCredential.user);
      
      console.log('Verification email sent');
      
      toast.success('Registration successful! Please check your email to verify your account.');
      return userCredential;
    }
    
    return null;
  } catch (error: any) {
    console.error('Firebase Registration error:', error);
    console.error('Error code:', error?.code);
    console.error('Error message:', error?.message);
    
    let message = 'Failed to register. Please try again.';
    
    if (error.code === 'auth/email-already-in-use') {
      message = 'This email is already registered. Please login or use a different email.';
    } else if (error.code === 'auth/invalid-email') {
      message = 'Invalid email address format.';
    } else if (error.code === 'auth/weak-password') {
      message = 'Password must be at least 6 characters long.';
    } else if (error.code === 'auth/operation-not-allowed') {
      message = 'Email/Password authentication is not enabled in Firebase Console. Please enable it.';
    } else if (error.code === 'auth/network-request-failed') {
      message = 'Network error. Please check your internet connection.';
    }
    
    toast.error(message);
    return null;
  }
};

/**
 * Login with email and password
 */
export const loginUser = async (
  email: string,
  password: string
): Promise<{ user: any; verified: boolean } | null> => {
  try {
    console.log('Attempting login for:', email);
    
    const userCredential = await signInWithEmailAndPassword(auth, email, password);
    const user = userCredential.user;
    
    console.log('Firebase login successful, UID:', user.uid);
    console.log('Email verified status:', user.emailVerified);
    
    // Check if email is verified
    if (!user.emailVerified) {
      console.warn('Email not verified for user:', email);
      // We allow login even if not verified for development/convenience, 
      // but we return the status so the UI can show a warning
      toast.warning('Your email is not verified. Some features may be limited.');
      return { user, verified: false };
    }
    
    console.log('Login successful and verified');
    toast.success('Login successful!');
    return { user, verified: true };
    
  } catch (error: any) {
    console.error('Firebase Login error:', error);
    console.error('Error code:', error?.code);
    console.error('Error message:', error?.message);
    
    let message = 'Failed to login. Please check your credentials.';
    
    if (error.code === 'auth/user-not-found' || error.code === 'auth/user-not-found-in-database') {
      message = 'No account found with this email address. Please register first.';
    } else if (error.code === 'auth/wrong-password') {
      message = 'Incorrect password. Please try again or reset your password.';
    } else if (error.code === 'auth/invalid-credential') {
      message = 'Invalid email or password. Please check your credentials and try again.';
    } else if (error.code === 'auth/too-many-requests') {
      message = 'Too many failed attempts. Please try again later or reset your password.';
    } else if (error.code === 'auth/invalid-email') {
      message = 'Invalid email address format.';
    } else if (error.code === 'auth/user-disabled') {
      message = 'This account has been disabled. Please contact support.';
    } else if (error.code === 'auth/network-request-failed') {
      message = 'Network error. Please check your internet connection or Firebase configuration (API Key, etc).';
    } else if (error.code === 'auth/operation-not-allowed') {
      message = 'Email/Password authentication is not enabled in Firebase Console. Please enable it in the Authentication tab.';
    }
    
    toast.error(message);
    return null;
  }
};

/**
 * Resend verification email
 */
export const resendVerificationEmail = async (user: any): Promise<boolean> => {
  try {
    if (!user) {
      toast.error('No user logged in');
      return false;
    }
    
    await sendEmailVerification(user);
    toast.success('Verification email sent! Please check your inbox.');
    return true;
  } catch (error: any) {
    console.error('Error resending verification email:', error);
    toast.error('Failed to send verification email. Please try again.');
    return false;
  }
};

/**
 * Logout user
 */
export const logoutUser = async (): Promise<void> => {
  try {
    await signOut(auth);
    toast.success('Logged out successfully');
  } catch (error: any) {
    console.error('Logout error:', error);
    toast.error('Failed to logout');
  }
};

/**
 * Get current authenticated user
 */
export const getCurrentUser = () => {
  return auth.currentUser;
};
